package com.student.dao;
import com.student.model.Mark; import com.student.util.DBConnection; import java.sql.*; import java.util.*;
public class MarkDAO {
 public void upsert(Mark m)throws SQLException{String q="MERGE INTO marks (student_id,course_id,marks,max_marks,remarks) KEY(student_id,course_id) VALUES(?,?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,m.getStudentId());p.setInt(2,m.getCourseId());p.setDouble(3,m.getMarks());p.setDouble(4,m.getMaxMarks());p.setString(5,m.getRemarks());p.executeUpdate();}}
 public List<Mark> findAll()throws SQLException{List<Mark> l=new ArrayList<>();String q="SELECT m.mark_id,m.student_id,m.course_id,m.marks,m.max_marks,m.remarks,s.first_name||' '||s.last_name student_name,c.course_name FROM marks m JOIN students s ON s.student_id=m.student_id JOIN courses c ON c.course_id=m.course_id ORDER BY s.first_name,c.course_name";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next()){Mark m=new Mark();m.setMarkId(r.getInt("mark_id"));m.setStudentId(r.getInt("student_id"));m.setCourseId(r.getInt("course_id"));m.setMarks(r.getDouble("marks"));m.setMaxMarks(r.getDouble("max_marks"));m.setRemarks(r.getString("remarks"));m.setStudentName(r.getString("student_name"));m.setCourseName(r.getString("course_name"));l.add(m);}}return l;}
 public List<Mark> findByStudent(int studentId)throws SQLException{List<Mark> l=new ArrayList<>();String q="SELECT m.mark_id,m.student_id,m.course_id,m.marks,m.max_marks,m.remarks,c.course_name FROM marks m JOIN courses c ON c.course_id=m.course_id WHERE m.student_id=? ORDER BY c.course_name";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,studentId);try(ResultSet r=p.executeQuery()){while(r.next()){Mark m=new Mark();m.setMarkId(r.getInt(1));m.setStudentId(r.getInt(2));m.setCourseId(r.getInt(3));m.setMarks(r.getDouble(4));m.setMaxMarks(r.getDouble(5));m.setRemarks(r.getString(6));m.setCourseName(r.getString(7));l.add(m);}}}return l;}
 public int count()throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM marks");ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}
}
